BOOL licensed = [NvsStreamingContext verifySdkLicenseFile:licensePath];
if (!licensed) { return nil; }
NvsStreamingContext *context = [NvsStreamingContext sharedInstanceWithFlags:flags];
return context;

if (width % 4 != 0 || height % 2 != 0) { return nil; }
uint64_t pixels = (uint64_t)width * (uint64_t)height;
uint64_t limit = (flags & NvsStreamingContextFlag_Support4KEdit) ? (uint64_t)3840 * 2160 : (uint64_t)1920 * 1080;
if (pixels > limit) { return nil; }
NvsVideoResolution videoRes = {0};
videoRes.imageWidth = width;
videoRes.imageHeight = height;
videoRes.imagePAR = (NvsRational){1, 1};
NvsRational fps = {30, 1};
NvsAudioResolution audioRes = {48000, 2, NvsAudSmpFmt_S16};
return [context createTimeline:&videoRes videoFps:&fps audioEditRes:&audioRes];

NSString *identifier = asset.localIdentifier;
if (identifier.length == 0) { return nil; }
NvsVideoClip *clip = [track appendClip:identifier];
return clip;

if (context == nil || timeline == nil || liveWindow == nil) { return NO; }
if (liveWindow.window == nil || CGRectIsEmpty(liveWindow.bounds)) { return NO; }
return [context connectTimeline:timeline withLiveWindow:liveWindow];

if (outputPath.length == 0 || cachePath.length == 0) { return NO; }
NSFileManager *fm = [NSFileManager defaultManager];
if (!isResuming && [fm fileExistsAtPath:cachePath]) {
    if (![fm removeItemAtPath:cachePath error:nil]) { return NO; }
}
if (![fm createDirectoryAtPath:cachePath withIntermediateDirectories:YES attributes:nil error:nil]) { return NO; }
NSMutableDictionary *config = [NSMutableDictionary dictionary];
config[NVS_COMPILE_ENABLE_BREAKPOINT_CONTINUATION] = @YES;
config[NVS_COMPILE_CACHE_FILE_PATH] = cachePath;
[context stop];
[context setCustomCompileVideoHeight:outputHeight];
return [context compileTimeline:timeline startTime:0 endTime:timeline.duration outputFilePath:outputPath videoResolutionGrade:NvsCompileVideoResolutionGradeCustom videoBitrateGrade:NvsCompileBitrateGradeHigh compileConfigurations:config flags:0];

guard width % 4 == 0, height % 2 == 0 else { return nil }
let pixels = UInt64(width) * UInt64(height)
let supports4K = (flags.rawValue & NvsStreamingContextFlag_Support4KEdit.rawValue) != 0
let limit: UInt64 = supports4K ? 3_840 * 2_160 : 1_920 * 1_080
guard pixels <= limit else { return nil }
var video = NvsVideoResolution(imageWidth: width, imageHeight: height, imagePAR: NvsRational(num: 1, den: 1), bitDepth: NvsVideoResolutionBitDepth(rawValue: 0))
var fps = NvsRational(num: 30, den: 1)
var audio = NvsAudioResolution(sampleRate: 48_000, sampleFormat: NvsAudioSampleFormat(rawValue: 1), channelCount: 2)
return context.createTimeline(&video, videoFps: &fps, audioEditRes: &audio)

guard !outputPath.isEmpty, !cachePath.isEmpty else { return false }
let fileManager = FileManager.default
if !isResuming, fileManager.fileExists(atPath: cachePath) {
    do { try fileManager.removeItem(atPath: cachePath) } catch { return false }
}
do { try fileManager.createDirectory(atPath: cachePath, withIntermediateDirectories: true) } catch { return false }
let config = NSMutableDictionary()
config[NVS_COMPILE_ENABLE_BREAKPOINT_CONTINUATION] = true as NSNumber
config[NVS_COMPILE_CACHE_FILE_PATH] = cachePath
context.stop()
context.setCustomCompileVideoHeight(height)
return context.compileTimeline(timeline, startTime: 0, endTime: timeline.duration, outputFilePath: outputPath, videoResolutionGrade: NvsCompileVideoResolutionGradeCustom, videoBitrateGrade: NvsCompileBitrateGradeHigh, compileConfigurations: config, flags: 0)
